from typing import List


class Solution:
    def isSolvable(self, words: List[str], result: str) -> bool:
        max_len = max(len(w) for w in words)
        R = len(result)
        if max_len > R or R > max_len + 1:
            return False
        idx = {}
        for w in words:
            for ch in w:
                if ch not in idx:
                    idx[ch] = len(idx)
        for ch in result:
            if ch not in idx:
                idx[ch] = len(idx)
        n = len(idx)
        if n > 10:
            return False
        leading = [False] * n
        for w in words:
            leading[idx[w[0]]] = True
        leading[idx[result[0]]] = True
        F = []
        U = []
        RC = []
        seen = set()
        for i in range(R):
            cnt = {}
            for w in words:
                if len(w) > i:
                    c = idx[w[len(w) - 1 - i]]
                    cnt[c] = cnt.get(c, 0) + 1
            rc = idx[result[R - 1 - i]]
            fixed = []
            unass = []
            for c, wt in cnt.items():
                if c in seen:
                    fixed.append((c, wt))
                else:
                    unass.append((c, wt))
            for p in range(len(unass)):
                if unass[p][0] == rc:
                    unass.append(unass.pop(p))
                    break
            F.append(fixed)
            U.append(unass)
            RC.append(rc)
            seen.update(cnt)
            seen.add(rc)
        CAND = [[tuple(d for d in range(10) if (m * d) % 10 == t)
                 for t in range(10)] for m in range(6)]
        assign = [-1] * n
        used = [False] * 10
        Rm1 = R - 1

        def dfs(ci, carry):
            if ci == R:
                return carry == 0
            S = 0
            for c, wt in F[ci]:
                S += assign[c] * wt
            return col_dfs(ci, carry, 0, S)

        def col_dfs(ci, carry, k, S):
            unass = U[ci]
            nu = len(unass)
            if k == nu:
                total = S + carry
                rc = RC[ci]
                if ci == Rm1:
                    if total >= 10:
                        return False
                    if assign[rc] < 0:
                        if used[total] or (total == 0 and leading[rc]):
                            return False
                        return True
                    return assign[rc] == total
                if assign[rc] < 0:
                    d = total % 10
                    if used[d] or (d == 0 and leading[rc]):
                        return False
                    assign[rc] = d
                    used[d] = True
                    if dfs(ci + 1, total // 10):
                        return True
                    used[d] = False
                    assign[rc] = -1
                    return False
                if assign[rc] != total % 10:
                    return False
                return dfs(ci + 1, total // 10)
            c, wt = unass[k]
            if k == nu - 1:
                rc = RC[ci]
                if rc == c:
                    m = wt - 1
                    t = (-(S + carry)) % 10
                    for d in CAND[m][t]:
                        if used[d] or (d == 0 and leading[c]):
                            continue
                        tot = S + wt * d + carry
                        if ci == Rm1:
                            if tot < 10:
                                return True
                            continue
                        assign[c] = d
                        used[d] = True
                        if dfs(ci + 1, tot // 10):
                            return True
                        used[d] = False
                        assign[c] = -1
                    return False
                if assign[rc] >= 0:
                    m = wt
                    t = (assign[rc] - S - carry) % 10
                    for d in CAND[m][t]:
                        if used[d] or (d == 0 and leading[c]):
                            continue
                        tot = S + wt * d + carry
                        if ci == Rm1:
                            if tot < 10:
                                return True
                            continue
                        assign[c] = d
                        used[d] = True
                        if dfs(ci + 1, tot // 10):
                            return True
                        used[d] = False
                        assign[c] = -1
                    return False
                lo = 1 if leading[c] else 0
                base = S + carry
                for d in range(lo, 10):
                    if used[d]:
                        continue
                    tot = base + wt * d
                    if ci == Rm1 and tot >= 10:
                        continue
                    rd = tot % 10
                    if rd == d or used[rd] or (rd == 0 and leading[rc]):
                        continue
                    assign[c] = d
                    assign[rc] = rd
                    used[d] = True
                    used[rd] = True
                    if ci == Rm1:
                        return True
                    if dfs(ci + 1, tot // 10):
                        return True
                    used[d] = False
                    used[rd] = False
                    assign[c] = -1
                    assign[rc] = -1
                return False
            lo = 1 if leading[c] else 0
            for d in range(lo, 10):
                if not used[d]:
                    used[d] = True
                    assign[c] = d
                    if col_dfs(ci, carry, k + 1, S + wt * d):
                        return True
                    used[d] = False
                    assign[c] = -1
            return False

        return dfs(0, 0)
