from typing import List

class Solution:
    def numFactoredBinaryTrees(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        arr.sort()
        dp = {}
        for i, a in enumerate(arr):
            count = 1
            for j in range(i):
                b = arr[j]
                if a % b == 0:
                    c = a // b
                    if c in dp:
                        count += dp[b] * dp[c]
            dp[a] = count % MOD
        return sum(dp.values()) % MOD
