from typing import List

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        TOP = m * n
        parent = list(range(m * n + 1))
        size = [1] * (m * n + 1)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        def idx(r, c):
            return r * n + c

        # Apply all hits: mark cells that had bricks with 2
        g = [row[:] for row in grid]
        for r, c in hits:
            if g[r][c] == 1:
                g[r][c] = 2

        # Union all remaining bricks; connect top row to virtual roof
        for r in range(m):
            for c in range(n):
                if g[r][c] == 1:
                    if r == 0:
                        union(idx(r, c), TOP)
                    if r + 1 < m and g[r + 1][c] == 1:
                        union(idx(r, c), idx(r + 1, c))
                    if c + 1 < n and g[r][c + 1] == 1:
                        union(idx(r, c), idx(r, c + 1))

        res = []
        dirs = ((-1, 0), (1, 0), (0, -1), (0, 1))
        for r, c in reversed(hits):
            if grid[r][c] == 0:
                res.append(0)
                continue
            # Restore the brick
            g[r][c] = 1
            old_roof = size[find(TOP)]
            if r == 0:
                union(idx(r, c), TOP)
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and g[nr][nc] == 1:
                    union(idx(r, c), idx(nr, nc))
            new_roof = size[find(TOP)]
            res.append(max(0, new_roof - old_roof - 1))

        res.reverse()
        return res
```

