Looking at this problem:

- We need the largest k×k sub-square where all row sums, column sums, and both diagonal sums are equal.
- With m, n ≤ 50, we can try each size k from largest to smallest, and each top-left position, using prefix sums for O(1)/O(k) checks:
  - **Row prefix sums** → row sum of any horizontal segment in O(1).
  - **Column prefix sums** → column sum of any vertical segment in O(1).
  - **Main diagonal prefix sums** (`diag[i][j] = grid[i][j] + diag[i-1][j-1]`) → main diagonal sum of a square in O(1) by subtracting the part above-left.
  - **Anti-diagonal prefix sums** (`anti[i][j] = grid[i][j] + anti[i-1][j+1]`) → anti-diagonal sum in O(1) by subtracting the part above-right.

For each candidate square, take the first row's sum as target, check both diagonals in O(1), then verify remaining rows and all columns with early break. Since k=1 is always magic, we always return a valid answer.

I verified against both examples: Example 1 returns 3 (square at rows 1–3, cols 1–3 sums to 12), Example 2 returns 2 (the [[3,3],[3,3]] block).

```python
from typing import List

class Solution:
    def largestMagicSquare(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Row prefix sums: row_pre[i][j] = sum(grid[i][0:j])
        row_pre = [[0] * (n + 1) for _ in range(m)]
        for i in range(m):
            ri = row_pre[i]
            gi = grid[i]
            for j in range(n):
                ri[j + 1] = ri[j] + gi[j]

        # Column prefix sums: col_pre[i][j] = sum(grid[0:i][j])
        col_pre = [[0] * n for _ in range(m + 1)]
        for i in range(m):
            ci = col_pre[i]
            ni = col_pre[i + 1]
            gi = grid[i]
            for j in range(n):
                ni[j] = ci[j] + gi[j]

        # Main diagonal prefix sums: diag[i][j] = sum of diagonal ending at (i, j)
        diag = [[0] * n for _ in range(m)]
        for i in range(m):
            gi = grid[i]
            di = diag[i]
            if i:
                up = diag[i - 1]
                di[0] = gi[0]
                for j in range(1, n):
                    di[j] = gi[j] + up[j - 1]
            else:
                for j in range(n):
                    di[j] = gi[j]

        # Anti-diagonal prefix sums: anti[i][j] = sum of anti-diagonal ending at (i, j)
        anti = [[0] * n for _ in range(m)]
        for i in range(m):
            gi = grid[i]
            ai = anti[i]
            if i:
                up = anti[i - 1]
                ai[n - 1] = gi[n - 1]
                for j in range(n - 1):
                    ai[j] = gi[j] + up[j + 1]
            else:
                for j in range(n):
                    ai[j] = gi[j]

        for k in range(min(m, n), 0, -1):
            for i in range(m - k + 1):
                col_top = col_pre[i]
                col_bot = col_pre[i + k]
                for j in range(n - k + 1):
                    r0 = row_pre[i]
                    target = r0[j + k] - r0[j]

                    # main diagonal check (O(1))
                    d = diag[i + k - 1][j + k - 1]
                    if i and j:
                        d -= diag[i - 1][j - 1]
                    if d != target:
                        continue

                    # anti-diagonal check (O(1))
                    a = anti[i + k - 1][j]
                    if i and j + k < n:
                        a -= anti[i - 1][j + k]
                    if a != target:
                        continue

                    # remaining row checks
                    ok = True
                    for r in range(i + 1, i + k):
                        rr = row_pre[r]
                        if rr[j + k] - rr[j] != target:
                            ok = False
                            break
                    if not ok:
                        continue

                    # column checks
                    for c in range(j, j + k):
                        if col_bot[c] - col_top[c] != target:
                            ok = False
                            break
                    if not ok:
                        continue

                    return k

        return 1
```

