from typing import List

class Solution:
    def minDays(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        N = m * n
        cells = [grid[i][j] for i in range(m) for j in range(n)]

        # Precompute in-bounds 4-directional neighbors (flattened indices)
        nbrs = [[] for _ in range(N)]
        for i in range(m):
            for j in range(n):
                idx = i * n + j
                if i > 0:
                    nbrs[idx].append(idx - n)
                if i + 1 < m:
                    nbrs[idx].append(idx + n)
                if j > 0:
                    nbrs[idx].append(idx - 1)
                if j + 1 < n:
                    nbrs[idx].append(idx + 1)

        def count_islands():
            seen = [False] * N
            islands = 0
            for s in range(N):
                if cells[s] == 1 and not seen[s]:
                    islands += 1
                    if islands > 1:
                        return islands
                    stack = [s]
                    seen[s] = True
                    while stack:
                        x = stack.pop()
                        for y in nbrs[x]:
                            if cells[y] == 1 and not seen[y]:
                                seen[y] = True
                                stack.append(y)
            return islands

        # Already disconnected (0 or >= 2 islands)?
        if count_islands() != 1:
            return 0

        land = [s for s in range(N) if cells[s] == 1]
        k = len(land)

        # Single land cell: removing it leaves 0 islands -> disconnected
        if k == 1:
            return 1

        seen = [0] * N
        gen = 0

        for r in land:
            # A cell with fewer than 2 land neighbors can never be critical
            deg = 0
            for y in nbrs[r]:
                if cells[y] == 1:
                    deg += 1
            if deg < 2:
                continue

            cells[r] = 0
            gen += 1
            start = land[0] if land[0] != r else land[1]
            seen[start] = gen
            cnt = 1
            stack = [start]
            while stack and cnt < k - 1:
                x = stack.pop()
                for y in nbrs[x]:
                    if cells[y] == 1 and seen[y] != gen:
                        seen[y] = gen
                        cnt += 1
                        stack.append(y)
            cells[r] = 1

            if cnt != k - 1:
                return 1

        # No single removal disconnects; 2 days always suffice
        return 2
```

Looking at this problem:

- Naive DP over all values 0..n is too slow for n up to 2×10⁹.
- Key insight: eating single oranges is only useful to reach the nearest multiple of 2 or 3, then divide. So from `n`, the optimal move is either:
  - eat `n % 2` oranges one-by-one (cost `n % 2` days), then eat `n/2` in one day (cost 1), then solve `n // 2`;
  - or eat `n % 3` oranges one-by-one (cost `n % 3` days), then eat `2*(n/3)` in one day (cost 1), then solve `n // 3`.

This gives `f(n) = min(n%2 + 1 + f(n//2), n%3 + 1 + f(n//3))` with base cases `f(0)=0, f(1)=1`. Eating more than `n%2` (or `n%3`) singles before dividing is never better since `f` is non-decreasing and `f(m+1) ≤ f(m)+1`.

The number of distinct states reachable via repeated `//2` and `//3` is about `log2(n) × log3(n)` ≈ 620 for n = 2×10⁹, so memoized recursion is very fast.

Verification:
- n=10: f(10)=min(0+1+f(5), 1+1+f(3)); f(5)=min(1+1+f(2), 2+1+1)=4; f(3)=min(1+1+1, 0+1+1)=2 → f(10)=min(5,4)=4 ✓
- n=6: f(6)=min(1+f(3), 1+f(2))=min(3,3)=3 ✓

