    def minDays(self, n: int) -> int:
        memo = {0: 0, 1: 1}

        def f(m: int) -> int:
            if m in memo:
                return memo[m]
            res = min(m % 2 + 1 + f(m // 2), m % 3 + 1 + f(m // 3))
            memo[m] = res
            return res

        return f(n)
```

