from typing import List

class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        n = len(bloomDay)
        if m * k > n:
            return -1

        def can_make(day: int) -> bool:
            bouquets = 0
            consecutive = 0
            for b in bloomDay:
                if b <= day:
                    consecutive += 1
                    if consecutive == k:
                        bouquets += 1
                        if bouquets >= m:
                            return True
                        consecutive = 0
                else:
                    consecutive = 0
            return False

        lo, hi = min(bloomDay), max(bloomDay)
        while lo < hi:
            mid = (lo + hi) // 2
            if can_make(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
