from typing import List


class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        n = len(grid)
        parent = list(range(4 * n * n))

        def find(x: int) -> int:
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        def node(i: int, j: int, t: int) -> int:
            return (i * n + j) * 4 + t

        for i in range(n):
            for j in range(n):
                c = grid[i][j]
                top = node(i, j, 0)
                right = node(i, j, 1)
                bottom = node(i, j, 2)
                left = node(i, j, 3)
                if c == '/':
                    union(top, left)
                    union(right, bottom)
                elif c == '\\':
                    union(top, right)
                    union(bottom, left)
                else:
                    union(top, right)
                    union(right, bottom)
                    union(bottom, left)
                if j + 1 < n:
                    union(right, node(i, j + 1, 3))
                if i + 1 < n:
                    union(bottom, node(i + 1, j, 0))

        return sum(1 for x in range(4 * n * n) if find(x) == x)
```

