                    # Zero occurrences of the preceding element
                    dp[i][j] = dp[i][j - 2]
                    # One or more occurrences, if preceding element matches s[i-1]
                    if p[j - 2] == s[i - 1] or p[j - 2] == '.':
                        dp[i][j] = dp[i][j] or dp[i - 1][j]
