from typing import List


class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        # Minimum removals needed: l = unmatched '(', r = unmatched ')'
        l = 0
        r = 0
        for c in s:
            if c == '(':
                l += 1
            elif c == ')':
                if l > 0:
                    l -= 1
                else:
                    r += 1

        n = len(s)
        results = []
        path = []

        def dfs(i, balance, l_rem, r_rem, prev_removed):
            if i == n:
                if l_rem == 0 and r_rem == 0:
                    results.append(''.join(path))
                return

            c = s[i]

            # Branch 1: remove this parenthesis (run-prefix rule avoids
            # redundant permutations within runs of identical parens).
            if c == '(':
                if l_rem > 0 and (i == 0 or s[i - 1] != '(' or prev_removed):
                    dfs(i + 1, balance, l_rem - 1, r_rem, True)
            elif c == ')':
                if r_rem > 0 and (i == 0 or s[i - 1] != ')' or prev_removed):
                    dfs(i + 1, balance, l_rem, r_rem - 1, True)

            # Branch 2: keep this character.
            if c == '(':
                path.append(c)
                dfs(i + 1, balance + 1, l_rem, r_rem, False)
                path.pop()
            elif c == ')':
                if balance > 0:
                    path.append(c)
                    dfs(i + 1, balance - 1, l_rem, r_rem, False)
                    path.pop()
            else:
                path.append(c)
                dfs(i + 1, balance, l_rem, r_rem, False)
                path.pop()

        dfs(0, 0, l, r, False)
        return list(set(results))
```

