from typing import List


class Solution:
    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:
        # Count soldiers in each row using binary search (all 1's are at the left).
        def count_soldiers(row: List[int]) -> int:
            lo, hi = 0, len(row)
            while lo < hi:
                mid = (lo + hi) // 2
                if row[mid] == 1:
                    lo = mid + 1
                else:
                    hi = mid
            return lo

        counts = [(count_soldiers(row), i) for i, row in enumerate(mat)]
        counts.sort()
        return [i for _, i in counts[:k]]
```

